mapper.select:
SELECT DISTINCT S.ID, S.MASTER_ID, S.NAME, S.DESCRIPTION, S.TYPE, S.SUB_ID, S.LEVEL, S.FID, S.ALIAS_SUB_ID, S.ORDER, S.SUB_IMG_ID, S.STATE, S.TOKEN, S.IS_PUBLIC, S.UPDATE_TIME, S.CREATE_TIME, S.INTRO_ON_OFF, S.TEMPLATE_ID, S.CERTIFICATES_FLAG, S.badge_id, S.badge_content, F.ID AS F_ID, F.NAME AS F_NAME, F.FILE_URL AS F_FILE_URL, F.SAVE_TYPE AS F_SAVE_TYPE, CASE WHEN s.master_id = #{masterId} THEN s.order ELSE sa.order END as orders, COALESCE(sum(sys.video_long),0) as sumVideoLong, sa.order as subjectAssociation_order, concat( '[', string_agg(distinct '"' || tags.tag_text || '"', ',' ), ']' ) AS course_tags, s.cpd_hours FROM GC_SUBJECT S
LEFT JOIN GC_USER_ACCESS_PERMISSION uap ON uap.sub_permission::jsonb @> to_jsonb(S.ID::integer) LEFT JOIN GC_USER_ACCESS UA ON UA.ID = UAP.USER_ACCESS_ID and ua.master_id = #{masterId} LEFT JOIN GC_USER "USER" ON "USER".ID = UA.USER_ID
LEFT JOIN GC_USER_ACCESS_PERMISSION uap ON uap.sub_permission::jsonb @> to_jsonb(S.ID::integer) LEFT JOIN GC_USER_ACCESS UA ON UA.ID = UAP.USER_ACCESS_ID LEFT JOIN GC_USER "USER" ON "USER".ID = UA.USER_ID
LEFT JOIN SYS_FILE F ON F.ID = S.SUB_IMG_ID left join gc_subject sub1 on sub1.fid = s.id LEFT JOIN gc_video v ON v.sub_id= sub1.id LEFT JOIN sys_file sys on sys.id=v.file_id LEFT JOIN gc_subject_association sa ON ( S.id = sa.subject_id OR s.fid = sa.subject_id ) AND sa.master_id = #{masterId} left join gc_subject_tags tags on tags.subject_id = s.id and( (sa.subject_id = tags.subject_id and tags.type = 1 and s.master_id = tags.master_id) or(tags.master_id = #{masterId})) and tags."status" = 0
1=1 and UA.role_json::text like concat('%','groupMember','%')
and s.fid =#{fid}
AND "user".id =#{userId}
AND v.id in
#{videoId}
AND( s.id in
#{subjectId}
or s.available_type = 1)
AND (S.name LIKE CONCAT( CONCAT( '%', #{subjectName}), '%' )
or ( V.VIDEO_NAME LIKE CONCAT( CONCAT( '%', #{videoInCourseName}), '%' ))
)
AND V.VIDEO_NAME LIKE CONCAT(CONCAT('%', #{videoName}),'%')
AND s.id not in
#{channelId}
and tags.tag_text = #{tag}
AND s.id in
#{subId}
and s.id is null
and tags.tag_text in
#{tagList}
AND s.id in
#{subId}
GROUP BY s.id, F.ID, sa.order
HAVING 1=2 or( 1=2
or (sumVideoLong >=#{durationMin1} and sumVideoLong<=#{durationMax1})
or (sumVideoLong >#{durationMin2} and sumVideoLong<=#{durationMax2})
or (sumVideoLong >#{durationMin3} and sumVideoLong<=#{durationMax3})
or (sumVideoLong >#{durationMin1})
)
ORDER BY orders,s.id

